import{_ as e,o as i,c as l,a2 as t}from"./chunks/framework.ClgMjOt7.js";const p=JSON.parse('{"title":"主な機能","description":"Palleriaで利用できる閲覧、検索、ブックマーク、ダウンロード機能。","frontmatter":{"title":"主な機能","description":"Palleriaで利用できる閲覧、検索、ブックマーク、ダウンロード機能。"},"headers":[],"relativePath":"guide/features.md","filePath":"guide/features.md","lastUpdated":1788759251000}'),r={name:"guide/features.md"};function o(d,a,n,s,c,h){return i(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="主な機能" tabindex="-1">主な機能 <a class="header-anchor" href="#主な機能" aria-label="Permalink to &quot;主な機能&quot;">​</a></h1><h2 id="ホームと閲覧" tabindex="-1">ホームと閲覧 <a class="header-anchor" href="#ホームと閲覧" aria-label="Permalink to &quot;ホームと閲覧&quot;">​</a></h2><p>ホームでは、おすすめ作品とフォロー中ユーザーの新着作品を切り替えて確認できます。</p><ul><li>イラスト、マンガ、小説の表示</li><li>複数ページ作品の閲覧</li><li>全画面画像ビューアー</li><li>関連作品と作者プロフィール</li><li>デイリー、ウィークリー、マンスリーランキング</li></ul><h2 id="検索" tabindex="-1">検索 <a class="header-anchor" href="#検索" aria-label="Permalink to &quot;検索&quot;">​</a></h2><p>作品、タグ、ユーザーを検索できます。タイトルやキャプション、完全一致などの条件を使い分け、ブックマーク数や並び順で結果を絞り込めます。</p><p>よく確認するタグはウォッチリストへ登録できます。最近見た作品と検索履歴から、途中だった探索へ戻ることもできます。</p><h2 id="ブックマークとフォロー" tabindex="-1">ブックマークとフォロー <a class="header-anchor" href="#ブックマークとフォロー" aria-label="Permalink to &quot;ブックマークとフォロー&quot;">​</a></h2><ul><li>公開・非公開ブックマーク</li><li>ユーザーのフォローと解除</li><li>ダウンロード時の自動ブックマーク</li><li>条件に応じた自動ダウンロード</li></ul><p>操作結果が反映されない場合は、通信状態を確認して画面を更新してください。</p><h2 id="ダウンロード" tabindex="-1">ダウンロード <a class="header-anchor" href="#ダウンロード" aria-label="Permalink to &quot;ダウンロード&quot;">​</a></h2><p>作品の単一ページ、または全ページを保存できます。設定から同時ダウンロード数を調整し、ダウンロードキューで進行状況を確認できます。</p><div class="info custom-block"><p class="custom-block-title">保存先へのアクセス</p><p>Androidのバージョンや選択した保存先によって、初回のみフォルダやメディアへのアクセス許可が表示される場合があります。</p></div><h2 id="androidとの連携" tabindex="-1">Androidとの連携 <a class="header-anchor" href="#androidとの連携" aria-label="Permalink to &quot;Androidとの連携&quot;">​</a></h2><p>Palleriaは共有されたPixiv URLやテキストを受け取り、対応する作品や検索画面を開けます。ホーム画面ウィジェットやライブ壁紙など、Android向けの連携機能も含まれます。</p>',15)])])}const _=e(r,[["render",o]]);export{p as __pageData,_ as default};
